var i=`0589-bolani`;var t=`world-0589`;var o=`AF`;var a=`south-asia`;var l=8;var r=64;var s={en:`Bolani`,ua:`Болані`};var g={en:`A traditional dish from Afghanistan, centered on all-purpose flour, potato, leek, cilantro. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: пшеничне борошно універсальне, картопля, цибуля-порей, кінза. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,400,`g`],[`water`,210,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:11,i:[[`potato`,480,`g`],[`leek`,190,`g`],[`cilantro`,20,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:17,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,65,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`plain-yogurt`,150,`g`]]}];var d={slug:i,id:t,country:`AF`,region:a,servings:8,minutes:64,title:s,text:g,steps:u};export{o as country,d as default,t as id,r as minutes,a as region,l as servings,i as slug,u as steps,g as text,s as title};